#### Merton model calibration ####import numpy as npfrom scipy.stats import normfrom scipy.optimize import root## Calibrate asset value and volatility def merton_calibration_residuals(    unknowns,    equity_value,    equity_volatility,    debt,    risk_free_rate,    maturity,):    # Extract proposed asset value and asset volatility from unknowns    asset_value, asset_volatility = unknowns    # Calculate d1 and d2    d1 = (np.log(asset_value / debt) +       (risk_free_rate + 0.5 * asset_volatility**2) * maturity) / (      asset_volatility * np.sqrt(maturity))    d2 = d1 - asset_volatility * np.sqrt(maturity)    # Calculate the model-implied equity value & volatility    implied_equity_value = asset_value * norm.cdf(d1) - debt * np.exp(        -risk_free_rate * maturity) * norm.cdf(d2)    implied_equity_volatility = (asset_value / equity_value) * norm.cdf(d1) * asset_volatility    # Calculate residuals for the numerical solver    equity_value_residual = implied_equity_value - equity_value    equity_volatility_residual = implied_equity_volatility - equity_volatility    return np.array([        equity_value_residual,        equity_volatility_residual,    ])def calibrate_merton(    equity_value,    equity_volatility,    debt,    risk_free_rate,    maturity,):        # Initial guesses for asset value and asset volatility    asset_value_guess = equity_value + debt    asset_volatility_guess = equity_volatility * equity_value / asset_value_guess    initial_guess = np.array([asset_value_guess, asset_volatility_guess])        # Use root() to solve merton_calibration_residuals()    solution = root(        merton_calibration_residuals,        initial_guess,        args=(            equity_value,            equity_volatility,            debt,            risk_free_rate,            maturity,        ),    )        # Check whether the solver succeeded    if not solution.success:        raise RuntimeError(            f"Merton calibration failed: {solution.message}"        )        # Extract and return calibrated asset value and asset volatility    asset_value, asset_volatility = solution.x    return asset_value, asset_volatility